'use strict';
let transactions=read('sagi-fuel',[]),parsedStatement=null,pendingImport=null;
const mapFields=[['date','Purchase date',true,['date','transactiondate','purchasedate']],['station','Station / location',false,['station','merchant','merchantname','location']],['gallons','US gallons',true,['gallons','quantity','volume']],['total','Diesel total (USD)',false,['fueltotal','total','amount','transactionamount']],['price','Unit price (USD / US gallon)',false,['unitprice','price','pricepergallon','ppg']],['id','Transaction ID',false,['transactionid','transactionnumber','invoice','reference']],['currency','Currency',false,['currency','currencycode']],['product','Fuel product',false,['product','fueltype','productname']]];
const providerSaved=read('sagi-provider','EFS/WEX');if([...$('provider').options].some(o=>o.value===providerSaved))$('provider').value=providerSaved;
function providerStatus(){$('providerStatus').innerHTML=`<span class="provider-tag">${esc($('provider').value)} · Setup required</span>`;}providerStatus();
$('provider').onchange=()=>{persist('sagi-provider',$('provider').value);providerStatus();pendingImport=null;$('importPreview').innerHTML='';};
$('fuelFile').onchange=async()=>{pendingImport=null;parsedStatement=null;$('importPreview').innerHTML='';$('mappingForm').hidden=true;const file=$('fuelFile').files[0];if(!file)return;if(file.size>2*1024*1024){$('importStatus').textContent='Choose a statement smaller than 2 MB.';return}try{parsedStatement=FuelCore.parseCSV(await file.text());$('importStatus').textContent=`${parsedStatement.rows.length} rows found. Match the columns, then review before importing.`;$('mappingFields').innerHTML=mapFields.map(([key,label,required,aliases])=>{let selected=parsedStatement.header.findIndex(h=>aliases.includes(h.toLowerCase().replace(/[^a-z]/g,'')));return `<label>${label}${required?' *':''}<select id="map_${key}" ${required?'required':''}><option value="">${required?'Choose a column':'Not included'}</option>${parsedStatement.header.map((h,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`}).join('');$('confirmUnits').checked=false;$('mappingForm').hidden=false;}catch(e){$('importStatus').textContent=e.message;}};
$('mappingForm').onchange=()=>{pendingImport=null;$('importPreview').innerHTML='';};
$('mappingForm').onsubmit=e=>{e.preventDefault();const map={};mapFields.forEach(([k])=>map[k]=$('map_'+k).value);const chosen=Object.values(map).filter(v=>v!=='');if(new Set(chosen).size!==chosen.length){toast('Each selected field needs its own column.');return}if(map.total===''&&map.price===''){toast('Map either a diesel total or a unit price.');return}pendingImport=FuelCore.review(parsedStatement,map,$('provider').value,transactions);const r=pendingImport,t=FuelCore.totals(r.valid);$('importPreview').innerHTML=`<div class="note"><b>${r.valid.length} ready to import · ${r.duplicates.length} duplicates skipped · ${r.invalid.length} invalid rows excluded</b>${money(t.total)} diesel purchases · ${t.gallons.toFixed(2)} US gallons</div>${r.invalid.length?`<details><summary>Review excluded rows</summary><div class="review-scroll">${r.invalid.map(x=>`<p>Row ${x.row}: ${esc(x.error)}</p>`).join('')}</div></details>`:''}<div class="review-scroll">${r.valid.slice(0,8).map(t=>`<div class="row"><span>${esc(t.date)} · ${esc(t.station)}</span><b>${money(t.total)}</b></div>`).join('')}${r.valid.length>8?'<p>Showing first 8 valid rows.</p>':''}</div><button class="primary" id="commitImport" ${r.valid.length?'':'disabled'}>Import ${r.valid.length} valid transactions</button>`;$('commitImport').onclick=()=>{if(!pendingImport?.valid.length)return;const next=[...transactions,...pendingImport.valid.map(t=>({...t,id:crypto.randomUUID(),tripId:'',importedAt:new Date().toISOString()}))];if(!persist('sagi-fuel',next))return;transactions=next;pendingImport=null;parsedStatement=null;$('importPreview').innerHTML='';$('mappingForm').hidden=true;$('fuelFile').value='';$('importStatus').textContent='Import complete. Link purchases to saved trips below.';renderFuel();toast('Fuel transactions imported.');};};
function downloadCSV(name,rows){const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const u=URL.createObjectURL(new Blob([rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function tripLabel(s){return `${s.origin} → ${s.destination} · ${new Date(s.date).toLocaleDateString()}`;}
function renderFuel(){const t=FuelCore.totals(transactions.filter(t=>t.product!=='DEF'));$('transactionCount').textContent=`${transactions.length} transactions`;const def=FuelCore.totals(transactions.filter(t=>t.product==='DEF'));$('fuelTotals').innerHTML=transactions.length?`<div class="purchase-metrics"><div><small>Diesel purchased</small><b>${money(t.total)}</b></div><div><small>US gallons</small><b>${t.gallons.toFixed(1)}</b></div><div><small>Weighted paid price / gal</small><b>${money(t.price)}</b></div><div><small>DEF purchases</small><b>${money(def.total)} · ${def.gallons.toFixed(2)} gal</b></div></div>`:'<p class="hint">No fuel purchases yet.</p>';$('usePaidPrice').disabled=!t.gallons;$('exportFuel').disabled=!transactions.length;$('clearFuel').disabled=!transactions.length;$('transactionList').innerHTML=[...transactions].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<div class="transaction"><header><div><b>${esc(t.station)}</b><br><small>${esc(t.date)} · ${esc(t.product||'Diesel')} · ${esc(t.provider)} · ${t.gallons.toFixed(2)} gal · ${money(t.price)}/gal</small></div><b>${money(t.total)}</b></header><label>Assign purchase to a saved trip<select data-transaction="${t.id}"><option value="">Unassigned</option>${saved.map(s=>`<option value="${s.id}" ${String(t.tripId)===String(s.id)?'selected':''}>${esc(tripLabel(s))}</option>`).join('')}</select></label><button class="text-button" data-delete-purchase="${t.id}">Delete purchase</button></div>`).join('');$('transactionList').querySelectorAll('[data-delete-purchase]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this purchase? Final trip costs remain unchanged.'))return;const next=transactions.filter(t=>t.id!==b.dataset.deletePurchase);if(persist('sagi-fuel',next)){transactions=next;renderFuel()}});$('transactionList').querySelectorAll('select').forEach(select=>select.onchange=()=>{const next=transactions.map(t=>t.id===select.dataset.transaction?{...t,tripId:select.value}:t);if(persist('sagi-fuel',next)){transactions=next;toast('Trip assignment updated.');}else renderFuel();});}window.renderFuel=renderFuel;renderFuel();
$('usePaidPrice').onclick=()=>{const t=FuelCore.totals(transactions.filter(t=>t.product!=='DEF'));if(!t.gallons)return;$('price').value=t.price.toFixed(3);tab('plan');if(last)calculate();toast('Diesel assumption updated from recorded purchases; not a current quote.');};
$('exportFuel').onclick=()=>{if(!transactions.length)return;downloadCSV('Truckload-fuel-purchases.csv',[['Date','Station','Gallons','Fuel Total','Unit Price','Transaction ID','Currency','Product','Provider','Assigned trip'],...transactions.map(t=>[t.date,t.station,t.gallons,t.total,t.price.toFixed(4),t.transactionId,'USD',t.product||'Diesel',t.provider,tripLabel(saved.find(s=>String(s.id)===String(t.tripId))||{origin:'Unassigned',destination:'',date:new Date().toISOString()})])]);};
$('clearFuel').onclick=()=>{if(!confirm('Remove all diesel and DEF purchases from this device? Saved estimates and final costs will remain.'))return;if(persist('sagi-fuel',[])){transactions=[];pendingImport=null;$('importPreview').innerHTML='';renderFuel();toast('Purchases removed.');}};
function localToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
$('purchaseDate').value=localToday();
document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{$('purchaseProduct').value=b.dataset.product;document.querySelectorAll('[data-product]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
function purchaseTotal(){const gallons=+$('purchaseGallons').value,price=+$('purchasePrice').value;if(gallons>0&&price>0)$('purchaseTotal').value=(gallons*price).toFixed(2);}
$('purchaseGallons').oninput=purchaseTotal;$('purchasePrice').oninput=purchaseTotal;
$('purchaseTotal').oninput=()=>{if(+$('purchaseGallons').value>0)$('purchasePrice').value=(+$('purchaseTotal').value/+$('purchaseGallons').value).toFixed(3);};
$('manualFuelForm').onsubmit=e=>{e.preventDefault();const gallons=+$('purchaseGallons').value,total=+$('purchaseTotal').value;if(!(gallons>0&&total>0&&Number.isFinite(total/gallons))){toast('Enter valid gallons and cost.');return}const next=[...transactions,{id:crypto.randomUUID(),date:$('purchaseDate').value,product:$('purchaseProduct').value,station:$('purchaseStation').value.trim()||'Manual purchase',gallons,total,price:total/gallons,provider:'Manual',transactionId:'',tripId:''}];if(persist('sagi-fuel',next)){transactions=next;$('manualFuelForm').reset();document.querySelector('[data-product="Diesel"]').click();$('purchaseDate').value=localToday();renderFuel();toast('Purchase saved.')}};
const finalFields=[['pay','Final load payment ($)'],['fuelGallons','Diesel consumed (US gallons)'],['fuel','Diesel consumed cost ($)'],['defGallons','DEF used (US gallons)'],['defCost','DEF cost ($)'],['tolls','Tolls ($)'],['scale','Weight scale ($)'],['reefer','Reefer fuel ($)'],['parking','Parking ($)'],['other','Driver pay and other deductions ($)'],['lumper','Final lumper cost ($)']];
function renderSaved(){
 $('savedList').innerHTML=saved.map((s,i)=>{const a=s.actual||{},legacy=!!s.actual&&!s.actual.completedAt;let final;try{final=TripCore.actual(a)}catch{}const initial={pay:s.pay,fuel:'',fuelGallons:'',defGallons:s.defGallons||0,defCost:s.defCost||0,tolls:s.tolls||0,scale:s.scale||0,reefer:s.reefer||0,parking:s.parking||0,other:(s.driver||0)+(s.deductions||0),lumper:s.lumper??''};if(legacy){['defCost','tolls','scale','reefer','parking'].forEach(k=>initial[k]=0);initial.other=a.other;initial.lumper='';}return `<article class="trip-card"><h3>${esc(s.origin)} → ${esc(s.destination)}</h3><small>${esc(s.loadNumber||'No load number')} · ${s.miles} total miles</small><h2>Estimated earnings: ${money(s.net)}</h2>${s.version!==2?'<p class="hint">Earlier estimate retained with its original cost assumptions.</p>':''}${s.lumperPending?'<p class="hint">Original estimate excludes a pending lumper charge.</p>':''}${final?`<div class="note"><b>Completed ${esc(a.completedAt)} · earned ${money(final.net)}</b>Final trip expenses: ${money(final.cost)}. Business costs are separate.</div>`:'<p class="note">Add final costs and completion date to count weekly earnings.</p>'}<details><summary>${s.actual?'Edit':'Enter'} final trip costs</summary><p class="hint">Enter final trip costs; use 0 if none. Exclude recurring bills and reimbursed costs. Do not also add excluded reimbursements to load pay.</p>${legacy?'<p class="note">Older costs are kept under other deductions. Avoid counting them twice.</p>':''}<form data-actual="${i}"><label>Trip completed on<input name="completedAt" type="date" value="${esc(a.completedAt||'')}" required></label><div class="grid">${finalFields.map(([k,label])=>`<label>${label}<input name="${k}" type="number" min="0" step="0.01" value="${esc(a[k]??initial[k]??0)}" required></label>`).join('')}<label>Lumper paid by<select name="lumperPayer">${[['unknown','Choose payer'],['company','Company'],['driver','Driver'],['broker','Broker'],['none','No lumper needed']].map(([v,l])=>`<option value="${v}" ${v===(a.lumperPayer||s.lumperPayer||'unknown')?'selected':''}>${l}</option>`).join('')}</select></label></div><label class="check"><input name="lumperDeduct" type="checkbox" ${(a.lumperDeduct??s.lumperDeduct)?'checked':''}>Deduct lumper from my earnings</label><button class="primary">Save completed trip</button><p class="actual-status" role="status"></p></form></details><details><summary>Manual input load/payment</summary><p>Pickup: ${esc(s.pickupAt||'Not entered')} · ${esc(s.pickupAddress||s.origin)}</p><p>Delivery: ${esc(s.deliveryAt||'Not entered')} · ${esc(s.deliveryAddress||s.destination)}</p><p>${esc(s.broker||'')} · ${esc(s.equipment||'')} · ${esc(s.weight||'—')} lb</p><p>${esc(s.notes||'')}</p></details><div class="actions"><button data-reuse="${i}">Check a similar trip</button><button data-remove="${i}" class="text-button">Delete trip</button></div></article>`}).join('')||'<div class="card">Save an estimate from Check numbers first.</div>';
 $('savedList').querySelectorAll('[data-actual]').forEach(f=>{f.elements.lumperPayer.onchange=()=>{f.elements.lumperDeduct.checked=f.elements.lumperPayer.value==='driver';if(f.elements.lumperPayer.value==='none')f.elements.lumper.value='0'};f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),a={completedAt:fd.get('completedAt'),lumperPayer:fd.get('lumperPayer'),lumperDeduct:fd.has('lumperDeduct')};finalFields.forEach(([k])=>a[k]=Number(fd.get(k)));try{const actual=TripCore.actual(a),next=saved.map((s,i)=>i===+f.dataset.actual?{...s,actual}:s);if(persist('sagi-trips',next)){saved=next;renderSaved();toast('Completed trip saved to your weekly earnings.')}}catch(e){f.querySelector('.actual-status').textContent=e.message}}});
 $('savedList').querySelectorAll('[data-reuse]').forEach(b=>b.onclick=()=>{const s=saved[+b.dataset.reuse];$('tripForm').reset();window.setActiveRatecon?.(null);[...tripText,...tripNumbers,'lumper','lumperPayer'].forEach(k=>{if(s[k]!=null)$(k).value=s[k]});$('miles').value=s.loadedMiles??(s.miles-s.deadhead);$('lumperDeduct').checked=!!s.lumperDeduct;last=null;tab('plan');calculate();toast('Details copied. Review costs and appointments.');});
 $('savedList').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const i=+b.dataset.remove;if(!confirm('Delete this trip and its final earnings from the dashboard? Documents and purchases remain.'))return;const id=saved[i].id,next=saved.filter((_,j)=>j!==i);if(persist('sagi-trips',next)){saved=next;const fuel=transactions.map(t=>String(t.tripId)===String(id)?{...t,tripId:''}:t);if(persist('sagi-fuel',fuel))transactions=fuel;renderSaved();}});
}
$('export').onclick=()=>{if(!saved.length){toast('Save an estimate first.');return}downloadCSV('Truckload-trips.csv',[['Load/reference','Pickup','Delivery','Estimated pay','Estimated expenses','Estimated earnings','Completed on','Final pay','Final expenses','Final earnings','Lumper paid by','Lumper cost','Lumper deducted'],...saved.map(s=>{let a;try{a=TripCore.actual(s.actual)}catch{}return [s.loadNumber,s.origin,s.destination,s.pay,s.cost,s.net,a?.completedAt,a?.pay,a?.cost,a?.net,a?.lumperPayer,a?.lumper,a?.lumperDeduct]})]);};
let budgets=read('truckload-business-budgets',[]);
const businessFields=[['insurance','Insurance ($/month)'],['truckNote','Truck note ($/month)'],['tags','Tags budget ($/month)'],['other','Other recurring costs ($/month)'],['fees','Fees ($/month)'],['maintenance','Maintenance ($/month)'],['repairs','Repairs ($/month)'],['meals','Meals ($/month)']];
$('businessFields').innerHTML=businessFields.map(([k,l])=>`<label>${l}<input id="b_${k}" type="number" min="0" step="0.01" value="0" required></label>`).join('');$('businessFrom').value=localToday();
function renderBusiness(){renderBusinessExpenses();const sorted=[...budgets].sort((a,b)=>b.from.localeCompare(a.from));$('businessHistory').innerHTML=sorted.map(b=>`<div class="card"><b>From ${esc(b.from)} · ${money(businessFields.reduce((n,[k])=>n+(b[k]||0),0))}/month</b><p>${businessFields.map(([k,l])=>esc(l.split(' ($')[0])+': '+money(b[k]||0)).join(' · ')}</p><button data-budget="${esc(b.from)}">Edit this budget</button></div>`).join('')||'<p>No business costs saved yet. Dashboard business costs currently use $0.</p>';$('businessHistory').querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>{const v=budgets.find(v=>v.from===b.dataset.budget);$('businessFrom').value=v.from;businessFields.forEach(([k])=>$('b_'+k).value=v[k]||0);$('businessStatus').textContent='Editing this effective date. Save to replace its amounts.'});}
$('businessForm').onsubmit=e=>{e.preventDefault();const b={from:$('businessFrom').value};businessFields.forEach(([k])=>b[k]=+$('b_'+k).value);try{TripCore.date(b.from);TripCore.budgetFor([b.from],[b]);const next=[...budgets.filter(v=>v.from!==b.from),b];if(persist('truckload-business-budgets',next)){budgets=next;renderBusiness();$('businessStatus').textContent='Saved. Weekly totals use this budget from its effective date.'}}catch(e){$('businessStatus').textContent=e.message}};
let businessExpenses=read('truckload-business-expenses',[]);
$('expenseDate').value=localToday();
function renderBusinessExpenses(){$('businessExpenseList').innerHTML=businessExpenses.map(x=>`<div class="card"><b>${esc(x.date)} · ${esc(x.category)} · ${money(x.amount)}</b><button type="button" data-expense="${esc(x.id)}">Delete expense</button></div>`).join('');$('businessExpenseList').querySelectorAll('[data-expense]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this business expense?'))return;const next=businessExpenses.filter(x=>x.id!==b.dataset.expense);if(persist('truckload-business-expenses',next)){businessExpenses=next;renderBusinessExpenses();}});}
$('businessExpenseForm').onsubmit=e=>{e.preventDefault();const x={id:crypto.randomUUID(),date:$('expenseDate').value,category:$('expenseCategory').value,amount:+$('expenseAmount').value};try{TripCore.date(x.date);if(!Number.isFinite(x.amount)||x.amount<=0)throw Error('Enter a positive amount.');const next=[...businessExpenses,x];if(persist('truckload-business-expenses',next)){businessExpenses=next;$('expenseAmount').value='';renderBusinessExpenses();toast('Business expense saved.');}}catch(e){toast(e.message)}};
const initialWeek=TripCore.week(localToday());$('weekDate').value=initialWeek.start;$('endDate').value=initialWeek.end;
function earningsRange(){const w=TripCore.weekly(saved,budgets,$('weekDate').value,$('endDate').value);const manual=businessExpenses.filter(x=>x.date>=w.start&&x.date<=w.end).reduce((n,x)=>n+x.amount,0);w.business+=manual;w.net-=manual;return w;}
function renderDashboard(){if(!$('weekDate').value)return;let w;try{w=earningsRange()}catch(e){$('dashboardTotals').textContent=e.message;$('dashboardTrips').innerHTML='';return}$('weekRange').textContent=`${w.start} through ${w.end} · ${w.rows.length} completed trips`;$('dashboardTotals').innerHTML='<div class="dashboard-grid">'+[['Gross earnings',w.gross],['Net earnings',w.net]].map(([l,v])=>`<div class="card"><small>${l}</small><h2>${money(v)}</h2></div>`).join('')+`</div><p class="note">${w.pending} saved trips are not finalized and are excluded.${budgets.some(b=>b.from<=w.end)?'':' No business cost budget applies yet; allocation is $0.'}</p>`;$('dashboardTrips').innerHTML=w.rows.map(s=>`<div class="card"><b>${esc(s.origin)} → ${esc(s.destination)}</b><p>${esc(s.actual.completedAt)} · ${esc(s.loadNumber||'No load number')} · earned ${money(TripCore.actual(s.actual).net)}</p></div>`).join('')||'<p>No completed trips in this date range.</p>';}
$('weekDate').onchange=renderDashboard;$('endDate').onchange=renderDashboard;
$('exportWeek').onclick=()=>{if(!$('weekDate').value)return;let w;try{w=earningsRange()}catch(e){toast(e.message);return}downloadCSV('Truckload-week-'+w.start+'.csv',[['Week starts',w.start],['Week ends',w.end],['Completed trips',w.rows.length],['Load payments',w.gross],['Trip expenses',w.expenses],['Trip earnings',w.earnings],['Allocated business costs',w.business],['Earnings after business costs',w.net],[],['Completion date','Load/reference','Pickup','Delivery','Pay','Expenses','Earnings'],...w.rows.map(s=>[s.actual.completedAt,s.loadNumber,s.origin,s.destination,s.actual.pay,TripCore.actual(s.actual).cost,TripCore.actual(s.actual).net])]);};
